retch\")\nfilteredCampaigns = $campaign == \"전체\" ? sourceCampaigns : @Filter(sourceCampaigns, \"label\", \"==\", $campaign)\nselectedCampaign = $campaign == \"전체\" ? null : @Find(sourceCampaigns, \"label\", $campaign)\ncampaignSummary = $campaign == \"전체\" ? Text(\"전체 보기에서는 성장 기여 1위가 **치간칫솔(CAMP_004)**입니다. W2 매출은 2,000,000원으로, 표본 내 기여도 98.7%가 가장 높습니다. 효율 측면에서는 **치약코팅칫솔(CAMP_003)**의 ROAS 383%, 목표 달성률 130.0%가 가장 우수합니다.\", \"sm\") : Text(\"선택 캠페인 **\" + selectedCampaign.label + \" (\" + selectedCampaign.id + \")**은 W2 매출 \" + @Format(selectedCampaign.w2, \"currency\", 0, \"KRW\") + \", 광고비 \" + @Format(selectedCampaign.spend, \"currency\", 0, \"KRW\") + \", ROAS \" + selectedCampaign.roas + \"%, 목표달성률 \" + selectedCampaign.attainment + \"%입니다. 원문 claim은 \" + selectedCampaign.claim + \"이며, 직접 계산 기준 증감은 \" + @Format(selectedCampaign.w2 - selectedCampaign.w1, \"currency\", 0, \"KRW\") + \"입니다.\", \"sm\")\ncampaignRevenueRows = @Each(filteredCampaigns, \"c\", {label: c.label + \" · \" + c.id, w1: c.w1, w2: c.w2})\ncampaignRoasRows = @Each(filteredCampaigns, \"c\", {label: c.label + \" · \" + c.id, roas: c.roas, target: c.target, attainment: c.attainment})\ncampaignContributionRows = @Each(filteredCampaigns, \"c\", {label: c.label + \" · \" + c.id, contribution: c.contribution})\ncampaignCharts = Grid([campaignRevenueCard, campaignMetricCard, campaignContributionCard], 3, 220, 3)\ncampaignRevenueCard = Card([Caption(\"캠페인 매출 W1/W2\"), Chart(\"bar\", campaignRevenueRows, \"label\", [\"w1\", \"w2\"], \"currency\", \"KRW\", false, 240)])\ncampaignMetricCard = Card([Caption($metric == \"매출\" ? \"W2 매출\" : ($metric == \"ROAS\" ? \"ROAS vs 목표\" : \"목표 달성률\")), $metric == \"매출\" ? Chart(\"bar\", @Each(filteredCampaigns, \"c\", {label: c.label + \" · \" + c.id, revenue: c.w2}), \"label\", [\"revenue\"], \"currency\", \"KRW\", false, 240) : ($metric == \"ROAS\" ? Chart(\"bar\", campaignRoasRows, \"label\", [\"roas\", \"target\"], \"percent\", null, false, 240) : Chart(\"bar\", campaignRoasRows, \"label\", [\"attainment\"], \"percent\", null, false, 240))])\ncampaignContributionCard = Card([Caption(\"성장 기여도\"), Chart(\"bar\", campaignContributionRows, \"label\", [\"contribution\"], \"percent\", null, false, 240)])\ncampaignInsight = Grid([campaignRankCard, campaignCheckCard], 2, 260, 3)\ncampaignRankCard = Card([Title(\"핵심 해석\", \"md\"), List([ListItem(\"성장 견인\", \"치간칫솔(CAMP_004)은 W1 1,000,000원 → W2 2,000,000원으로 직접 계산상 +1,000,000원 상승.\"), ListItem(\"효율 우위\", \"치약코팅칫솔(CAMP_003)은 ROAS 383%, 목표 294%, 달성률 130.0%로 표본 내 최고 효율.\"), ListItem(\"신규 진입\", \"치약(CAMP_010)은 W1 0원에서 W2 90,000원 발생. 이력 부족으로 판단 보수적 접근 필요.\")], \"bullet\")], \"soft\", 3, 3)\ncampaignCheckCard = Card([Title(\"검증 포인트\", \"md\"), List([ListItem(\"치약코팅칫솔 claim 점검\", \"원문 claim은 +300,000원이지만 표의 W1/W2는 2,000,000원→2,000,000원입니다. 원문 수치 확인 필요.\"), ListItem(\"예산 증액 표현 점검\", \"Section 4 및 sourceActions는 100,000원→100,000원을 '증액'으로 표현합니다. 수치상 변경 0원이므로 실제 증액 여부 검증 필요.\"), ListItem(\"치간칫솔 해석\", \"OOB 맥락보다 재고·전환 효율 이슈가 더 큰 제약으로 제시되어, 예산보다 재고/상품구성 확인이 우선입니다.\")], \"bullet\")], \"soft\", 3, 3)\n\nriskSection = Card([riskHead, riskControls, riskSummary, riskCharts, riskDetails], \"outline\", 3, 3)\nriskHead = Row([Title(\"재고 위험 및 매출 방어\", \"md\"), Spacer(), Badge(@Format(@Sum(sourceRisks.risk), \"currency\", 0, \"KRW\"), \"danger\"), Badge(@Duration(@Sum(sourceRisks.hours) * 3600, \"short\"), \"warning\")], 2)\nriskControls = Row([SegmentedControl($sortRisk, [\"위험금액\", \"품절시간\"], true)], 3)\nsortedRisks = $sortRisk == \"위험금액\" ? @Sort(sourceRisks, \"risk\", \"desc\") : @Sort(sourceRisks, \"hours\", \"desc\")\nriskSummary = Text(\"최근 2주 기준 총 추정 위험 금액은 **\" + @Format(@Sum(sourceRisks.risk), \"currency\", 0, \"KRW\") + \"**입니다. 위험 상위 VID는 기능성 칫솔 6개입(VID_0019), 치약코팅칫솔 50개입(VID_0022), 기능성 칫솔 12개입(VID_0018) 순이며, 품절 시간이 길수록 매출 방어 우선순위가 높습니다. 단, 모든 시간 값은 **최근 2주 누적 시간**으로만 해석해야 하며 특정 주차 시간으로 재해석하면 안 됩니다.\", \"sm\")\nriskRows = @Each(sortedRisks, \"r\", {id: r.id, risk: r.risk, hours: r.hours, revenue: r.revenue, share: r.share})\nriskCharts = Grid([riskAmountCard, riskHoursCard, riskRevenueCard], 3, 220, 3)\nriskAmountCard = Card([Caption(\"VID별 추정 위험 금액\"), Chart(\"bar\", riskRows, \"id\", [\"risk\"], \"currency\", \"KRW\", false, 240)])\nriskHoursCard = Card([Caption(\"VID별 품절 시간\"), Chart(\"bar\", riskRows, \"id\", [\"hours\"], \"number\", null, false, 240)])\nriskRevenueCard = Card([Caption(\"VID별 광고 매출\"), Chart(\"bar\", riskRows, \"id\", [\"revenue\"], \"currency\", \"KRW\", false, 240)])\ntopRiskList = @Each(@Take(sortedRisks, 3), \"r\", ListItem(r.id + \" · \" + r.label, r.period + \" · 위험 \" + r.riskText + \" · 연결 캠페인 \" + r.campaign))\nriskDetails = Grid([riskPriorityCard, riskTableCard], 2, 280, 3)\nriskPriorityCard = Card([Title(\"우선 재고 조치\", \"md\"), List(topRiskList, \"number\"), Text(\"VID_0019는 137시간 품절과 2,000,000원 위험으로 최상위입니다. VID_0022는 치약코팅칫솔의 효율 개선 흐름을 제약하고, VID_0018은 기능성 칫솔 계열의 저활용 문제와 함께 해석해야 합니다.\", \"sm\")], \"soft\", 3, 3)\nriskTableRows = @Each(@Take(sortedRisks, 5), \"r\", [r.id, r.label, r.period, r.riskText, r.campaign])\nriskTableCard = Card([Title(\"상위 위험 VID 상세\", \"md\"), Table([\"VID\", \"상품\", \"기간\", \"위험금액\", \"연결 캠페인\"], riskTableRows)], \"soft\", 3, 3)\n\nactionSection = Card([actionHead, actionIntro, actionCards], \"outline\", 3, 3)\nactionHead = Row([Title(\"우선순위 액션\", \"md\"), Spacer(), Badge(@Plural(@Count(sourceActions), \"추천\"), \"info\")], 2)\nactionIntro = Text(\"원문 추천을 그대로 보존하되, 숫자와 서술의 합치 여부를 함께 표시했습니다. 특히 예산 추천은 **수치상 0원 변경**이면 증액이 아니라 '검증 필요'로 해석했습니다.\", \"sm\", \"muted\")\nactionCards = Col(@Each(sourceActions, \"a\", Card([Row([Badge(\"우선순위 \" + a.rank, a.rank == \"1\" ? \"danger\" : (a.rank == \"2\" ? \"warning\" : \"neutral\")), Badge(a.source, \"purple\")], 1, null, null, true), Text(a.action, \"sm\", null, \"semibold\"), Text(a.evidence, \"sm\"), Row([Badge(a.impact == \"정량화 불가\" ? \"불확실성 높음\" : \"효과 추정 제한\", \"warning\"), Badge(@Includes(a.action, \"100,000원에서 100,000원으로\") ? \"수치상 0원 변경\" : \"원문 수치와 합치\", @Includes(a.action, \"100,000원에서 100,000원으로\") ? \"danger\" : \"success\")], 1, null, null, true), Text(@Includes(a.action, \"100,000원에서 100,000원으로\") ? \"해석: 원문은 '증액'이라고 표현하지만 before/after 값이 동일합니다. 실제 증액안인지, 시스템 추천 문구 오류인지 확인 후 제안해야 합니다.\" : \"해석: 직접 조치보다 상태 점검·모니터링 성격이 강한 권고입니다.\", \"xs\", \"muted\")], \"soft\", 3, 3)), 3)\n\nsourceSection = Card([Title(\"원문 출처 및 범위\", \"md\"), sourceBlocks], \"outline\", 3, 3)\nsourceBlocks = Grid([sourceBlock1, sourceBlock2, sourceBlock3], 3, 220, 3)\nsourceBlock1 = Card([Caption(\"Section 1–2\"), Text(\"벤더 KPI와 경영진 요약은 sourceKpis와 원문 서술을 기준으로 구성했습니다. KPI 카드에는 W1/W2 원문 표기와 직접 계산을 함께 노출했습니다.\", \"sm\")], \"soft\", 3, 3)\nsourceBlock2 = Card([Caption(\"Section 3–5\"), Text(\"캠페인 비교, OOB/저활용 해석, 우선순위 액션은 sourceCampaigns 및 sourceActions의 ID, ROAS, 목표값, 원문 권고를 직접 반영했습니다. 제공되지 않은 캠페인별 CTR/CVR/AOV 이력은 생성하지 않았습니다.\", \"sm\")], \"soft\", 3, 3)\nsourceBlock3 = Card([Caption(\"Section 7\"), Text(\"재고 위험 차트와 우선순위는 sourceRisks의 최근 2주 hours, risk, revenue, campaign 필드를 그대로 사용했습니다. 품절 시간은 주차별 값이 아니라 최근 2주 누적값으로만 표기했습니다.\", \"sm\")], \"soft\", 3, 3)","status":"ready","published":false,"created_at":"2026-10-20T09:54:52.880848+00:00"}}

